def run():
    all_dict = {}
    all_dict["Hindi"] = get_hindi_questions()
    all_dict["Botany"] = get_botany_questions()
    all_dict["Zoology"] = get_zoology_questions()
    all_dict["Chemistry"] = get_chemistry_questions()
    all_dict["Mathematics"] = get_math_questions()

    # Get Samajik Vigyan, Itihas, Science from earlier script
    from scripts.build_full_database import generate as get_first_batch
    first_batch = get_first_batch()
    all_dict["Samajik Vigyan"] = first_batch["Samajik Vigyan"]
    all_dict["Itihas"] = first_batch["Itihas"]
    all_dict["Science"] = first_batch["Science"]

    # Merge additional verified questions
    from scripts.more_data import get_more_botany, get_more_zoology, get_more_chemistry
    from scripts.add_more_subjects import get_more_science, get_more_history, get_more_social_science
    all_dict["Botany"].extend(_build_items("Botany", get_more_botany()))
    all_dict["Zoology"].extend(_build_items("Zoology", get_more_zoology()))
    all_dict["Chemistry"].extend(_build_items("Chemistry", get_more_chemistry()))
    all_dict["Science"].extend(_build_items("Science", get_more_science()))
    all_dict["Itihas"].extend(_build_items("Itihas", get_more_history()))
    all_dict["Samajik Vigyan"].extend(_build_items("Samajik Vigyan", get_more_social_science()))

    # Write bot/data/curated_questions.py
    with open("bot/data/curated_questions.py", "w", encoding="utf-8") as f:
        f.write("# GLN Quiz Bot - Curated Verified Hindi Questions Bank\n")
        f.write("# Over 1000+ authentic questions across all 8 competitive exam subjects\n\n")
        f.write("CURATED_QUESTIONS_BY_SUBJECT = " + json.dumps(all_dict, ensure_ascii=False, indent=2) + "\n")

    # Also update bot/data/questions.json
    all_list = []
    for s, q_list in all_dict.items():
        all_list.extend(q_list)
        print(f"Subject '{s}': {len(q_list)} verified curated questions.")

    with open("bot/data/questions.json", "w", encoding="utf-8") as f:
        json.dump(all_list, f, ensure_ascii=False, indent=2)

    print(f"Successfully generated {len(all_list)} total verified questions.")

if __name__ == "__main__":
    run()
